def split_csv(line):
    fields = []
    i = 0
    n = len(line)
    if n == 0:
        return ['']
    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            field = []
            closed = False
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    field.append(line[i])
                    i += 1
            if not closed:
                return None
            # after closing quote must be comma or end of line
            if i == n:
                fields.append(''.join(field))
                break
            elif line[i] == ',':
                fields.append(''.join(field))
                i += 1
                if i == n:
                    fields.append('')
                    break
                continue
            else:
                return None
        else:
            # unquoted field
            j = i
            while j < n and line[j] != ',':
                if line[j] == '"':
                    return None
                j += 1
            fields.append(line[i:j])
            if j == n:
                break
            else:
                i = j + 1
                if i == n:
                    fields.append('')
                    break
    return fields

